module cfg_search (input clk, input rst_n, input start, input [4:0] rule_count, input [5:0][39:0] rule_data, input [127:0] text_data, output reg [7:0] result_start, output reg [7:0] result_length, output reg [127:0] result_substr, output reg done); reg [25:0] table [15:0][15:0]; reg [25:0] start_symbol_mask; reg [15:0] max_start; reg [7:0] max_length; reg [127:0] max_substr_reg; reg done_flag; reg [2:0] state; localparam IDLE = 3'd0, PARSING = 3'd1, PROCESSING = 3'd2, DONE = 3'd3; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; max_length <= 8'd0; max_start <= 16'd0; max_substr_reg <= 16'd0; done_flag <= 1'b0; end else begin case (state) IDLE: begin if (start) state <= PARSING; end PARSING: begin state <= PROCESSING; end PROCESSING: begin if (1) begin done_flag <= 1'b1; state <= DONE; end end DONE: begin endcase end end assign result_start = max_start; assign result_length = max_length; assign result_substr = max_substr_reg; assign done = done_flag; endmodule